  let total_a = clamp(grain_a + top_a * (1.0 - grain_a), 0.0, 1.0);
  let rgb = select(vec3f(0.0), mix(grain_rgb * grain_a, vec3f(1.0), top_a) / total_a, total_a > 0.001);
  return vec4f(clamp(rgb, vec3f(0.0), vec3f(1.0)), total_a);
